"""
Hook installers for the Agents service.

Installs lifecycle hooks for AI coding tools (Claude, OpenCode, Codex)
that register/deregister sessions via HTTP callbacks.
"""

import json
import logging
import os
import shutil
import subprocess
import sys
from pathlib import Path

from .constants import CLAUDE_DEREGISTER_TIMEOUT_S, CLAUDE_HOOK_TIMEOUT_S
from .exceptions import AgentHookError

logger = logging.getLogger(__name__)


def _find_qbraid_binary() -> str | None:
    """Find the qbraid binary path, checking PATH first, then common locations."""
    # Already on PATH?
    found = shutil.which("qbraid")
    if found:
        return found

    # Check the venv that qbraid_core is installed in
    venv_bin = Path(sys.executable).parent / "qbraid"
    if venv_bin.exists():
        return str(venv_bin)

    return None


def ensure_qbraid_on_path() -> str:
    """Ensure `qbraid` is available on PATH. Symlinks to /usr/local/bin if needed.

    Returns:
        The path to the qbraid binary.

    Raises:
        AgentHookError: If qbraid binary cannot be found or symlinked.
    """
    found = shutil.which("qbraid")
    if found:
        return found

    binary = _find_qbraid_binary()
    if not binary:
        raise AgentHookError(
            "Cannot find qbraid binary. Install qbraid-cli first: pip install qbraid-cli"
        )

    # Try to symlink to /usr/local/bin
    symlink_dir = Path("/usr/local/bin")
    symlink_path = symlink_dir / "qbraid"

    if symlink_dir.exists() and os.access(str(symlink_dir), os.W_OK):
        try:
            if symlink_path.exists() or symlink_path.is_symlink():
                symlink_path.unlink()
            symlink_path.symlink_to(binary)
            logger.info("Symlinked %s -> %s", symlink_path, binary)
            return str(symlink_path)
        except OSError as e:
            logger.warning("Could not symlink to /usr/local/bin: %s", e)

    # Try with sudo
    try:
        subprocess.run(
            ["sudo", "ln", "-sf", binary, str(symlink_path)],
            check=True,
            capture_output=True,
            timeout=30,
        )
        logger.info("Symlinked (via sudo) %s -> %s", symlink_path, binary)
        return str(symlink_path)
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired, FileNotFoundError) as e:
        logger.warning("Could not symlink via sudo: %s", e)

    raise AgentHookError(
        f"Found qbraid at {binary} but cannot add it to PATH. "
        f"Run: sudo ln -sf {binary} /usr/local/bin/qbraid"
    )


# Marker strings used to identify qBraid hooks in settings files.
_HOOK_MARKER = "qbraid agents register"


def _make_register_cmd() -> str:
    """Build a shell command that registers a session via the local CLI.

    The hook shell's $PPID is the agent process (e.g. claude).
    We inject it into the JSON payload so the registry has the real PID.
    """
    # Read stdin JSON and inject "pid": $PPID before piping to register.
    # $PPID in the hook shell is the agent process (e.g. claude PID).
    # Use sed to inject pid field into the JSON object.
    return (
        "INPUT=$(cat); "
        "echo \"$INPUT\" | sed 's/^{/{\"pid\":'$PPID',/' "
        "| qbraid agents register 2>/dev/null; true"
    )


def _make_deregister_cmd() -> str:
    """Build a shell command that deregisters a session via the local CLI."""
    return (
        "INPUT=$(cat); "
        "echo \"$INPUT\" | sed 's/^{/{\"pid\":'$PPID',/' "
        "| qbraid agents deregister 2>/dev/null; true"
    )


def _hook_group_contains(hook_group: dict, marker: str) -> bool:
    """Check if a hook group dict contains the marker string in any command."""
    if not isinstance(hook_group, dict):
        return False
    for hook in hook_group.get("hooks", []):
        if isinstance(hook, dict) and marker in hook.get("command", ""):
            return True
        if isinstance(hook, dict) and marker in hook.get("url", ""):
            return True
    return False


# ---------------------------------------------------------------------------
# Claude Code hooks
# ---------------------------------------------------------------------------


def install_claude_hooks() -> dict:
    """Merge SessionStart/SessionEnd hooks into ~/.claude/settings.json.

    Hooks register sessions via `qbraid agents register` CLI command (writes
    to local registry) and optionally notify JupyterLab if server.json exists.

    Preserves any existing user hooks. qBraid hooks are identified by marker strings.

    Returns:
        Dict with status and path.
    """
    settings_path = Path.home() / ".claude" / "settings.json"
    settings_path.parent.mkdir(parents=True, exist_ok=True)

    settings: dict = {}
    if settings_path.exists():
        try:
            with open(settings_path, "r", encoding="utf-8") as f:
                settings = json.load(f)
        except (json.JSONDecodeError, OSError) as e:
            logger.warning("Could not read Claude settings.json, creating fresh: %s", e)
            settings = {}

    hooks = settings.setdefault("hooks", {})
    marker = _HOOK_MARKER

    register_cmd = _make_register_cmd()
    deregister_cmd = _make_deregister_cmd()

    # SessionStart — remove old hooks (both extension curl and CLI versions)
    start_list = hooks.get("SessionStart", [])
    if not isinstance(start_list, list):
        start_list = []
    start_list = [
        h
        for h in start_list
        if not _hook_group_contains(h, marker)
        and not _hook_group_contains(h, "qbraid-lab/dashboard/sessions")
    ]
    start_list.append(
        {
            "matcher": "",
            "hooks": [
                {
                    "type": "command",
                    "command": register_cmd,
                    "timeout": CLAUDE_HOOK_TIMEOUT_S,
                }
            ],
        }
    )
    hooks["SessionStart"] = start_list

    # SessionEnd — remove old hooks. ``marker`` is "qbraid agents register"
    # (matches SessionStart), so we ALSO have to filter on the deregister
    # command — otherwise SessionEnd hooks accumulate one duplicate per install
    # call, since neither existing filter's substring appears in the deregister
    # command. Observed in the wild with 100+ dupes.
    end_list = hooks.get("SessionEnd", [])
    if not isinstance(end_list, list):
        end_list = []
    end_list = [
        h
        for h in end_list
        if not _hook_group_contains(h, marker)
        and not _hook_group_contains(h, "qbraid agents deregister")
        and not _hook_group_contains(h, "qbraid-lab/dashboard/sessions")
    ]
    end_list.append(
        {
            "matcher": "",
            "hooks": [
                {
                    "type": "command",
                    "command": deregister_cmd,
                    "timeout": CLAUDE_DEREGISTER_TIMEOUT_S,
                }
            ],
        }
    )
    hooks["SessionEnd"] = end_list

    # PreToolUse — permission routing via qBraid agent manager
    permission_marker = "qbraid-permission-hook"
    pre_tool_list = hooks.get("PreToolUse", [])
    if not isinstance(pre_tool_list, list):
        pre_tool_list = []
    pre_tool_list = [h for h in pre_tool_list if not _hook_group_contains(h, permission_marker)]

    # Find the permission_hook.py script path
    hook_script = Path(__file__).parent / "permission_hook.py"
    python_path = sys.executable

    pre_tool_list.append(
        {
            "matcher": "",
            "hooks": [
                {
                    "type": "command",
                    "command": (
                        f'[ -f "{hook_script}" ] && {python_path} '
                        f'"{hook_script}" 2>/dev/null || true '
                        f"# {permission_marker}"
                    ),
                    "timeout": 35,  # Slightly longer than the hook's internal timeout
                }
            ],
        }
    )
    hooks["PreToolUse"] = pre_tool_list

    settings["hooks"] = hooks

    try:
        with open(settings_path, "w", encoding="utf-8") as f:
            json.dump(settings, f, indent=2)
        logger.info("Installed Claude hooks in %s", settings_path)
    except Exception as e:
        raise AgentHookError(f"Error writing Claude hooks: {e}") from e

    return {"status": "installed", "path": str(settings_path)}


# ---------------------------------------------------------------------------
# OpenCode hooks (plugin file)
# ---------------------------------------------------------------------------

_OPENCODE_PLUGIN_TEMPLATE = """\
import type {{ Plugin }} from "opencode/plugin"
import {{ execSync }} from "child_process"

function registerViaCli(payload: Record<string, unknown>): void {{
  try {{
    execSync(`echo '${{JSON.stringify(payload)}}' | qbraid agents register`, {{
      stdio: "ignore", timeout: 5000
    }});
  }} catch {{}}
}}

function deregisterViaCli(payload: Record<string, unknown>): void {{
  try {{
    execSync(`echo '${{JSON.stringify(payload)}}' | qbraid agents deregister`, {{
      stdio: "ignore", timeout: 3000
    }});
  }} catch {{}}
}}

export const QBraidSessionTracker: Plugin = async ({{ directory }}) => {{
  return {{
    event: async ({{ event }}) => {{
      if (event.type === "session.created") {{
        registerViaCli({{
          tool_id: "codeq", session_id: event.properties?.sessionID,
          cwd: directory, pid: process.pid,
          port: process.env.OPENCODE_PORT
        }});
      }}
      if (event.type === "session.deleted") {{
        deregisterViaCli({{
          session_id: event.properties?.sessionID, tool_id: "codeq"
        }});
      }}
    }}
  }}
}}
"""


def install_opencode_hooks() -> dict:
    """Write the qBraid session tracker plugin for OpenCode.

    Returns:
        Dict with status and path.
    """
    plugin_dir = Path.home() / ".config" / "opencode" / "plugins"
    plugin_dir.mkdir(parents=True, exist_ok=True)
    plugin_path = plugin_dir / "qbraid-session-tracker.ts"

    content = _OPENCODE_PLUGIN_TEMPLATE

    try:
        with open(plugin_path, "w", encoding="utf-8") as f:
            f.write(content)
        logger.info("Installed OpenCode plugin at %s", plugin_path)
    except Exception as e:
        raise AgentHookError(f"Error installing OpenCode plugin: {e}") from e

    return {"status": "installed", "path": str(plugin_path)}


# ---------------------------------------------------------------------------
# Codex hooks
# ---------------------------------------------------------------------------


def install_codex_hooks() -> dict:
    """Write .codex/hooks.json with SessionStart/Stop hooks.

    Returns:
        Dict with status and path.
    """
    hooks_dir = Path.home() / ".codex"
    hooks_dir.mkdir(parents=True, exist_ok=True)
    hooks_path = hooks_dir / "hooks.json"

    register_cmd = (
        'SID="${QBRAID_SESSION_ID:-}"; '
        'echo \'{"tool_id":"codex","pid":\'$PPID\',"cwd":"\'$(pwd)\'"\' '
        '| sed "s/}$/$([ -n \\"$SID\\" ] && echo \',\\"session_id\\":\\"\'$SID\'\\"\')/" '
        '| sed "s/$/}/" '
        "| qbraid agents register 2>/dev/null; true"
    )
    deregister_cmd = (
        'echo \'{"tool_id":"codex","pid":\'$PPID\'}\' '
        "| qbraid agents deregister 2>/dev/null; true"
    )

    hooks_config: dict = {}
    if hooks_path.exists():
        try:
            with open(hooks_path, "r", encoding="utf-8") as f:
                hooks_config = json.load(f)
        except (json.JSONDecodeError, OSError):
            hooks_config = {}

    hooks = hooks_config.setdefault("hooks", {})

    # SessionStart — remove old hooks (both extension and CLI versions)
    start_list = hooks.get("SessionStart", [])
    if not isinstance(start_list, list):
        start_list = []
    start_list = [
        h
        for h in start_list
        if not _hook_group_contains(h, _HOOK_MARKER)
        and not _hook_group_contains(h, "qbraid agents register")
    ]
    start_list.append(
        {
            "hooks": [
                {
                    "type": "command",
                    "command": register_cmd,
                    "timeout": 5,
                }
            ],
        }
    )
    hooks["SessionStart"] = start_list

    # Stop — remove old hooks (both extension and CLI versions)
    stop_list = hooks.get("Stop", [])
    if not isinstance(stop_list, list):
        stop_list = []
    stop_list = [
        h
        for h in stop_list
        if not _hook_group_contains(h, _HOOK_MARKER)
        and not _hook_group_contains(h, "qbraid agents deregister")
    ]
    stop_list.append(
        {
            "hooks": [
                {
                    "type": "command",
                    "command": deregister_cmd,
                    "timeout": 5,
                }
            ],
        }
    )
    hooks["Stop"] = stop_list

    hooks_config["hooks"] = hooks

    try:
        with open(hooks_path, "w", encoding="utf-8") as f:
            json.dump(hooks_config, f, indent=2)
        logger.info("Installed Codex hooks at %s", hooks_path)
    except Exception as e:
        raise AgentHookError(f"Error writing Codex hooks: {e}") from e

    return {"status": "installed", "path": str(hooks_path)}


# ---------------------------------------------------------------------------
# Aggregate install / uninstall
# ---------------------------------------------------------------------------


def install_all_hooks() -> dict[str, dict]:
    """Install hooks for all supported CLI tools.

    Ensures `qbraid` is on PATH before installing hooks.

    Returns:
        Dict mapping tool name to install result.
    """
    # Verify qbraid is callable — hooks depend on it
    qbraid_path = ensure_qbraid_on_path()
    logger.info("Using qbraid at: %s", qbraid_path)

    results: dict[str, dict] = {}
    for name, installer in [
        ("claude", install_claude_hooks),
        ("codeq", install_opencode_hooks),
        ("codex", install_codex_hooks),
    ]:
        try:
            results[name] = installer()
        except Exception as e:
            logger.error("Failed to install %s hooks: %s", name, e)
            results[name] = {"status": "error", "error": str(e)}

    return results


def uninstall_all_hooks() -> dict[str, dict]:
    """Remove qBraid hooks from all supported CLI tools.

    Returns:
        Dict mapping tool name to uninstall result.
    """
    results: dict[str, dict] = {}
    markers = [
        _HOOK_MARKER,
        "qbraid agents register",
        "qbraid agents deregister",
        "qbraid-permission-hook",
    ]

    def _matches_any_marker(hook_group: dict) -> bool:
        return any(_hook_group_contains(hook_group, m) for m in markers)

    # Claude: remove hook entries from settings.json
    try:
        settings_path = Path.home() / ".claude" / "settings.json"
        if settings_path.exists():
            with open(settings_path, "r", encoding="utf-8") as f:
                settings = json.load(f)
            hooks = settings.get("hooks", {})
            changed = False
            for hook_name in ("SessionStart", "SessionEnd", "PreToolUse"):
                hook_list = hooks.get(hook_name, [])
                if isinstance(hook_list, list):
                    filtered = [h for h in hook_list if not _matches_any_marker(h)]
                    if len(filtered) != len(hook_list):
                        hooks[hook_name] = filtered
                        if not filtered:
                            del hooks[hook_name]
                        changed = True
            if changed:
                with open(settings_path, "w", encoding="utf-8") as f:
                    json.dump(settings, f, indent=2)
            results["claude"] = {"status": "uninstalled"}
        else:
            results["claude"] = {"status": "not_found"}
    except Exception as e:
        results["claude"] = {"status": "error", "error": str(e)}

    # OpenCode: remove plugin file
    try:
        plugin_path = Path.home() / ".config" / "opencode" / "plugins" / "qbraid-session-tracker.ts"
        if plugin_path.exists():
            plugin_path.unlink()
            results["codeq"] = {"status": "uninstalled"}
        else:
            results["codeq"] = {"status": "not_found"}
    except Exception as e:
        results["codeq"] = {"status": "error", "error": str(e)}

    # Codex: remove hook entries from hooks.json
    try:
        hooks_path = Path.home() / ".codex" / "hooks.json"
        if hooks_path.exists():
            with open(hooks_path, "r", encoding="utf-8") as f:
                hooks_config = json.load(f)
            hooks = hooks_config.get("hooks", {})
            changed = False
            for hook_name in ("SessionStart", "Stop"):
                hook_list = hooks.get(hook_name, [])
                if isinstance(hook_list, list):
                    filtered = [h for h in hook_list if not _matches_any_marker(h)]
                    if len(filtered) != len(hook_list):
                        hooks[hook_name] = filtered
                        changed = True
            if changed:
                with open(hooks_path, "w", encoding="utf-8") as f:
                    json.dump(hooks_config, f, indent=2)
            results["codex"] = {"status": "uninstalled"}
        else:
            results["codex"] = {"status": "not_found"}
    except Exception as e:
        results["codex"] = {"status": "error", "error": str(e)}

    return results
